"use client";
import { useEffect, useState, type CSSProperties } from "react";
import useEmblaCarousel from "embla-carousel-react";
import Image from "next/image";

// Curated popular destinations, ordered by real tour count (most popular first).
// `count` is the live `total` from each country's tour-list cache
// (tsgroup.s3.amazonaws.com/cache/tour-list-pages/<url>.json), snapshotted on
// 2026-06-12 — refresh manually when it drifts. Images are real, high-res hero
// shots hand-picked from each country's own tours (crisp + representative); the
// old /images/home/destinations/*.jpg thumbnails were only 400px and blurred
// when scaled up to these tall cards.
const CDN = "https://tsgroup.s3.amazonaws.com/media";
const DESTINATIONS: {
  name: string;
  region: string;
  url: string;
  image: string;
  count: number;
}[] = [
  { name: "Turkey", region: "Europe", url: "turkey-tours", count: 2678, image: `${CDN}/53555/conversions/AdobeStock_126013644-1-high.jpg` },
  { name: "Vietnam", region: "Asia", url: "vietnam-tours", count: 422, image: `${CDN}/129549/conversions/Emperor-cruise-Halong-high.jpg` },
  { name: "Egypt", region: "Africa", url: "egypt-tours", count: 414, image: `${CDN}/116283/conversions/6698fe612300001c00f7e89c-high.jpg` },
  { name: "Greece", region: "Europe", url: "greece-tours", count: 261, image: `${CDN}/116545/conversions/Patmos-Tour-(7)-high.jpg` },
  { name: "Italy", region: "Europe", url: "italy-tours", count: 233, image: `${CDN}/35098/conversions/Roma-Italy-(15)-high.jpg` },
  { name: "Nepal", region: "Asia", url: "nepal-tours", count: 233, image: `${CDN}/124179/conversions/1713711804730-high.jpg` },
  { name: "Tanzania", region: "Africa", url: "tanzania-tours", count: 228, image: `${CDN}/63123/conversions/CgFELWJWsAA7fy1-high.jpg` },
  { name: "Kenya", region: "Africa", url: "kenya-tours", count: 213, image: `${CDN}/63610/conversions/How-many-days-do-I-need-on-safari-in-Masai-Mara-high.jpg` },
  { name: "India", region: "Asia", url: "india-tours", count: 205, image: `${CDN}/63178/conversions/golden-triangle-tour-with-a-stay-in-goa-high.jpg` },
  { name: "Sri Lanka", region: "Asia", url: "sri-lanka-tours", count: 141, image: `${CDN}/118276/conversions/MIRISSA-high.jpg` },
  { name: "Peru", region: "South America", url: "peru-tours", count: 99, image: `${CDN}/95523/conversions/1933-1-high.jpg` },
  { name: "United Kingdom", region: "Europe", url: "united-kingdom-tours", count: 53, image: `${CDN}/108160/conversions/london-river-cruise-(5)-high.jpg` },
  { name: "Colombia", region: "South America", url: "colombia-tours", count: 46, image: `${CDN}/122198/conversions/DSC00531-high.jpg` },
  { name: "Spain", region: "Europe", url: "spain-tours", count: 36, image: `${CDN}/108404/conversions/Hot-Air-Balloon-Experience-from-Madrid-(2)-high.jpg` },
];

// Line-arrow icon (←/→) matching the rest of the new design (see tour-carousel).
function Arrow({ dir }: { dir: "left" | "right" }) {
  return (
    <svg
      width={18}
      height={18}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {dir === "left" ? (
        <>
          <path d="M19 12H5" />
          <path d="M11 19l-7-7 7-7" />
        </>
      ) : (
        <>
          <path d="M5 12h14" />
          <path d="M13 5l7 7-7 7" />
        </>
      )}
    </svg>
  );
}

// Arrow chrome via inline styles — with preflight off + global Bootstrap,
// arbitrary tw- classes for these don't apply reliably (same as tour-carousel).
const arrowStyle = (side: "left" | "right"): CSSProperties => ({
  appearance: "none",
  WebkitAppearance: "none",
  border: "1px solid #e2dced",
  color: "#14101c",
  background: "#fff",
  zIndex: 3,
  [side]: "-22px",
  boxShadow: "0 6px 16px rgba(20,16,28,0.16), 0 2px 5px rgba(20,16,28,0.10)",
});

const PopularDestinations = () => {
  const [emblaRef, emblaApi] = useEmblaCarousel({
    align: "start",
    containScroll: "trimSnaps",
    slidesToScroll: 1,
    breakpoints: {
      "(min-width: 640px)": { slidesToScroll: 2 },
      "(min-width: 1024px)": { slidesToScroll: 3 },
      "(min-width: 1280px)": { slidesToScroll: 5 },
    },
  });
  const [nav, setNav] = useState({ prev: false, next: false });

  useEffect(() => {
    if (!emblaApi) return;
    const update = () =>
      setNav({ prev: emblaApi.canScrollPrev(), next: emblaApi.canScrollNext() });
    update();
    emblaApi.on("select", update);
    emblaApi.on("reInit", update);
    return () => {
      emblaApi.off("select", update);
      emblaApi.off("reInit", update);
    };
  }, [emblaApi]);

  return (
    <section className="tw-pt-4 md:tw-pt-6 tw-pb-12 md:tw-pb-16 tw-font-display">
      <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
        <div className="tw-flex tw-flex-col sm:tw-flex-row tw-items-start sm:tw-items-end tw-justify-between tw-gap-2 sm:tw-gap-6 tw-mb-10">
          <div>
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Popular destinations
            </h2>
            <p className="tw-mt-1.5 tw-mb-0 tw-text-sm tw-text-[#6b6577] sm:tw-whitespace-nowrap">
              The countries travelers are exploring most right now.
            </p>
          </div>
          <a
            href="/worldwide-tours"
            title="All Worldwide Tours"
            className="tw-shrink-0 tw-text-[14px] tw-font-semibold tw-text-[#854ec9] hover:tw-text-[#6a3da4] tw-no-underline tw-inline-flex tw-items-center tw-gap-1.5 tw-transition-colors tw-whitespace-nowrap"
          >
            All destinations
            <span aria-hidden>→</span>
          </a>
        </div>

        {/* On mobile the viewport bleeds past the container padding so cards
            clip at the screen edge; per-slide padding restores the inset. */}
        <div className="tw-relative -tw-mx-6 md:tw-mx-0">
          {nav.prev && (
            <button
              type="button"
              onClick={() => emblaApi?.scrollPrev()}
              aria-label="Scroll left"
              style={arrowStyle("left")}
              className="tw-absolute tw-top-[42%] tw-hidden md:tw-grid tw-place-items-center tw-h-11 tw-w-11 tw-rounded-full"
            >
              <Arrow dir="left" />
            </button>
          )}

          <div ref={emblaRef} className="tw-overflow-hidden">
            <div className="tw-flex md:-tw-ml-6">
              {DESTINATIONS.map((d, index) => (
                <div
                  key={d.url}
                  // Gap lives as each slide's left padding (pl). On mobile the
                  // wrapper bleeds to the screen edge, so the first slide's pl
                  // is the left inset and the last slide adds a matching right
                  // inset (pr) — otherwise trimSnaps leaves the last card flush
                  // against the edge. Basis is padded by the same amount so all
                  // card images stay equal width. Desktop uses a 24px gap
                  // absorbed by the row's -ml-6 (matches the tour carousels).
                  className={`tw-min-w-0 tw-flex-none tw-pl-4 md:tw-pl-6 ${
                    index === DESTINATIONS.length - 1
                      ? "tw-pr-4 md:tw-pr-0 tw-basis-[calc(62%+2rem)] sm:tw-basis-[calc(40%+2rem)] md:tw-basis-1/4 lg:tw-basis-1/5"
                      : "tw-basis-[calc(62%+1rem)] sm:tw-basis-[calc(40%+1rem)] md:tw-basis-1/4 lg:tw-basis-1/5"
                  }`}
                >
                  <a
                    href={"/" + d.url}
                    title={"Worldwide " + d.name + " Tours"}
                    className="tw-group tw-no-underline tw-block tw-relative tw-overflow-hidden tw-rounded-2xl"
                  >
                    <div className="tw-relative tw-aspect-[3/4] tw-w-full tw-overflow-hidden tw-rounded-2xl tw-bg-[#f3f1f7]">
                      <Image
                        fill
                        src={d.image}
                        alt={d.name}
                        sizes="(max-width: 640px) 62vw, (max-width: 1024px) 33vw, 20vw"
                        className="tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-[1.06]"
                        loading="lazy"
                      />
                      <span
                        aria-hidden
                        className="tw-absolute tw-inset-0 tw-pointer-events-none"
                        style={{
                          background:
                            "linear-gradient(180deg, rgba(0,0,0,0) 35%, rgba(20,16,28,0.78) 100%)",
                        }}
                      />
                      <div className="tw-absolute tw-inset-x-0 tw-bottom-0 tw-z-[2] tw-px-[18px] tw-pt-4 tw-pb-4 tw-text-white">
                        <div className="tw-text-[11px] tw-font-semibold tw-uppercase tw-tracking-[0.06em] tw-opacity-85">
                          {d.region}
                        </div>
                        <div className="tw-text-[22px] tw-font-extrabold tw-leading-tight tw-tracking-[-0.02em] tw-mt-0.5 tw-text-balance">
                          {d.name}
                        </div>
                        <span
                          className="tw-inline-block tw-mt-2.5 tw-rounded-full tw-px-2.5 tw-py-1 tw-text-[11.5px] tw-font-semibold"
                          style={{
                            background: "rgba(255,255,255,0.18)",
                            border: "1px solid rgba(255,255,255,0.28)",
                            backdropFilter: "blur(6px)",
                            WebkitBackdropFilter: "blur(6px)",
                          }}
                        >
                          {(Math.ceil(d.count / 100) * 100).toLocaleString(
                            "en-US"
                          )}
                          <span className="tw-relative tw-top-[-1px]">+</span>{" "}
                          tours &amp; activities
                        </span>
                      </div>
                    </div>
                  </a>
                </div>
              ))}
            </div>
          </div>

          {nav.next && (
            <button
              type="button"
              onClick={() => emblaApi?.scrollNext()}
              aria-label="Scroll right"
              style={arrowStyle("right")}
              className="tw-absolute tw-top-[42%] tw-hidden md:tw-grid tw-place-items-center tw-h-11 tw-w-11 tw-rounded-full"
            >
              <Arrow dir="right" />
            </button>
          )}
        </div>
      </div>
    </section>
  );
};

export default PopularDestinations;
